        {
            success = true,
            message = "Database connection successful.",
            serverTime = result?.ToString(),
            buildCommit = Environment.GetEnvironmentVariable("RAILWAY_GIT_COMMIT_SHA") ?? "local",
            featureContract = "inspector_quote_travel_v1"
        });
    }
    catch (Exception ex)
    {
