    try
    {
        await using var conn = new NpgsqlConnection(connectionString);
        await conn.OpenAsync();
        await EnsureMappingTablesAsync(conn);

        var mappings = new List<object>();
        const string mappingSql = @"
SELECT
    canonical_field_name,
    threed_column_name,
    threed_label,
    source_table_name,
    source_list_name,
    invoice_item_id,
    invoice_item_name,
