        await using (var cmd = new NpgsqlCommand(mappingSql, conn))
        {
            cmd.Parameters.AddWithValue("inspector_id", inspectorId);
            await using var reader = await cmd.ExecuteReaderAsync();

            while (await reader.ReadAsync())
